nta.declaration:
// =====================================================================
// Cross-Traffic Intersection Management System
// Conflict-aware M/M/c Queue Model  (set c = 1 for M/M/1, c = 2 for M/M/2)
// Team B6
//
// IDEA:
//   - N vehicles approach a 4-way intersection.
//   - Each vehicle belongs to an AXIS:
//        axis 0 = North-South (vertical path)
//        axis 1 = East-West   (horizontal path)
//   - Two cars on DIFFERENT axes have crossing paths => they CONFLICT.
//   - Two cars on the SAME axis do NOT conflict (they pass each other).
//   - The controller may allow up to c cars to cross at the same time,
//     but ONLY if they are all on the same axis (no conflict).
//

//   Never have a North-South car and an East-West car crossing together.
// =====================================================================

const int N = 4;          // number of vehicles
const int c = 2;          // servers: 1 = M/M/1, 2 = M/M/2  

// How many cars are currently crossing on each axis.

int[0,N] crossingNS = 0;  // cars crossing on North-South axis right now
int[0,N] crossingEW = 0;  // cars crossing on East-West  axis right now



chan request[N];   // vehicle -> controller : "I want to cross"
chan grant[N];     // controller -> vehicle : "you may cross"
chan done[N];      // vehicle -> controller : "I have cleared the intersection"


const int[0,1] axisOf[N] = {0, 0, 1, 1};


int totalCrossing() {
    return crossingNS + crossingEW;
}


bool canGrant(int axis) {
    if (totalCrossing() >= c) return false;
    if (axis == 0) return crossingEW == 0;   // NS car needs EW empty
    else           return crossingNS == 0;   // EW car needs NS empty
}

template.declaration:
// The controller chooses which waiting car to admit.
// "select" lets UPPAAL try every vehicle id non-deterministically,
// so the model explores all admission orders (tutorial section 4).

nta.system:
// Assign each vehicle an id and an axis.
// Vehicles 0,1 travel North-South (axis 0).
// Vehicles 2,3 travel East-West  (axis 1).
// This gives us guaranteed conflict pairs to test the safety property.
Vehicle0 = Vehicle(0, 0);
Vehicle1 = Vehicle(1, 0);
Vehicle2 = Vehicle(2, 1);
Vehicle3 = Vehicle(3, 1);
Ctrl     = Controller();

system Vehicle0, Vehicle1, Vehicle2, Vehicle3, Ctrl;
